/**
 * Shared vanilla JavaScript for navigation toggle (no Bootstrap JS)
 * and live basket badge synchronization via localStorage.
 */
(function () {
  "use strict";

  var CART_STORAGE_KEY = "sweetOvenCart";

  function initNavbarToggle() {
    var toggleBtn = document.querySelector(".navbar-toggler");
    var navCollapse = document.getElementById("mainNavbar");

    if (!toggleBtn || !navCollapse) {
      return;
    }

    toggleBtn.addEventListener("click", function () {
      var isExpanded = navCollapse.classList.toggle("show");
      toggleBtn.setAttribute("aria-expanded", String(isExpanded));
    });

    // Close mobile menu when a nav link is selected
    var navLinks = navCollapse.querySelectorAll(".nav-link");
    navLinks.forEach(function (link) {
      link.addEventListener("click", function () {
        if (navCollapse.classList.contains("show")) {
          navCollapse.classList.remove("show");
          toggleBtn.setAttribute("aria-expanded", "false");
        }
      });
    });

    // Allow Escape key to close an open mobile menu
    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && navCollapse.classList.contains("show")) {
        navCollapse.classList.remove("show");
        toggleBtn.setAttribute("aria-expanded", "false");
        toggleBtn.focus();
      }
    });
  }

  function getSavedCartCount() {
    try {
      var raw = localStorage.getItem(CART_STORAGE_KEY);
      if (!raw) {
        return 0;
      }
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) {
        return 0;
      }
      return parsed.reduce(function (total, item) {
        var qty = Number(item && item.quantity);
        return total + (Number.isFinite(qty) && qty > 0 ? qty : 0);
      }, 0);
    } catch (error) {
      return 0;
    }
  }

  function updateNavCartBadge() {
    var badge = document.getElementById("navCartCount");
    if (!badge) {
      return;
    }
    var count = getSavedCartCount();
    badge.textContent = String(count);
    badge.setAttribute("aria-label", count + " items in cart");
  }

  document.addEventListener("DOMContentLoaded", function () {
    initNavbarToggle();
    updateNavCartBadge();
  });

  // Expose helper so page scripts can refresh the badge after Add-to-Basket actions
  window.SweetOvenNav = {
    updateCartBadge: updateNavCartBadge
  };
})();

/* ==========================================================================
   The Sweet Oven - Home Page Stylesheet (index.html)
   Loaded AFTER Bootstrap 5.3.3 CSS & css/styles.css
   ========================================================================== */

.nav-cart-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.35rem;
  height: 1.35rem;
  padding: 0 0.35rem;
  margin-left: 0.3rem;
  border-radius: 999px;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1;
}

/* Hero Section */
.hero-section {
  background: linear-gradient(135deg, var(--color-cream) 0%, var(--color-pink-soft) 100%);
  border-bottom: 1px solid var(--color-border);
}

.eyebrow-pill {
  display: inline-block;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
  padding: 0.35rem 0.9rem;
  border-radius: 999px;
}

.hero-title {
  font-size: clamp(2rem, 3.8vw, 3.1rem);
  color: var(--color-brown);
}

.hero-lead {
  font-size: 1.08rem;
  color: var(--color-muted);
  max-width: 38rem;
}

.hero-illustration {
  width: 100%;
  max-width: 480px;
  height: auto;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
}

.hero-meta-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  font-size: 0.94rem;
  color: var(--color-brown);
}

.hero-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.meta-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-caramel);
  flex-shrink: 0;
}

/* Promise Pillars */
.promise-card {
  height: 100%;
  padding: 1.35rem;
  border-left: 4px solid var(--color-caramel);
}

.promise-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.3rem;
  height: 2.3rem;
  border-radius: var(--radius-sm);
  background-color: var(--color-pink-soft);
  color: var(--color-brown);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: 0.75rem;
}

/* Featured Bakes Filter & Cards */
.filter-pill-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

.filter-pill {
  background-color: var(--color-surface);
  border: 1.5px solid var(--color-border);
  color: var(--color-brown);
  font-weight: 700;
  font-size: 0.9rem;
  padding: 0.42rem 0.95rem;
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.filter-pill:hover {
  background-color: var(--color-pink-soft);
  border-color: var(--color-caramel);
}

.filter-pill.is-active {
  background-color: var(--color-brown);
  border-color: var(--color-brown);
  color: var(--color-cream);
}

.bake-card {
  height: 100%;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.bake-card-media {
  background-color: var(--color-cream);
  padding: 1rem;
  display: flex;
  align-items: center;
  justify-content: center;
  border-bottom: 1px solid var(--color-border);
  position: relative;
}

.bake-card-media img {
  width: 100%;
  max-width: 220px;
  height: 155px;
  object-fit: contain;
}

.bake-tag {
  position: absolute;
  top: 0.75rem;
  left: 0.75rem;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-size: 0.76rem;
  font-weight: 700;
  padding: 0.24rem 0.65rem;
  border-radius: 999px;
}

.bake-price {
  font-family: var(--font-heading);
  font-size: 1.25rem;
  font-weight: 700;
  color: var(--color-caramel-dark);
}

.bake-meta {
  font-size: 0.85rem;
  color: var(--color-muted);
}

/* Weekly Bake Schedule */
.schedule-card {
  height: 100%;
  padding: 1.2rem;
  position: relative;
}

.schedule-card.is-today {
  border: 2px solid var(--color-caramel);
  background-color: var(--color-pink-soft);
}

.today-pill {
  background-color: var(--color-caramel);
  color: #FFFFFF;
  font-size: 0.74rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 999px;
}

/* Customer Highlights */
.quote-card {
  height: 100%;
  padding: 1.35rem;
}

.quote-stars {
  color: var(--color-caramel);
  font-weight: 700;
  letter-spacing: 0.08em;
}

/* Newsletter & Feedback Banner */
.newsletter-box {
  background-color: var(--color-surface);
  border: 2px solid var(--color-pink);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
}

.empty-state-box {
  background-color: var(--color-surface);
  border: 1.5px dashed var(--color-input-border);
  border-radius: var(--radius-md);
  padding: 2.25rem 1.5rem;
  text-align: center;
}

.status-toast {
  background-color: var(--color-brown);
  color: var(--color-cream);
  border-left: 5px solid var(--color-pink);
  border-radius: var(--radius-sm);
  padding: 0.85rem 1.1rem;
  font-weight: 600;
}

.field-error-msg {
  color: #9E2A2B;
  font-size: 0.86rem;
  font-weight: 700;
  margin-top: 0.35rem;
}

@media (max-width: 575.98px) {
  .bake-card-media img {
    height: 135px;
  }
}

/* ==========================================================================
   The Sweet Oven - About Page Stylesheet (pages/about.html)
   Loaded AFTER Bootstrap 5.3.3 CSS & ../css/styles.css
   ========================================================================== */

.nav-cart-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
