}

.baker-illustration {
  width: 100%;
  max-width: 450px;
  height: auto;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
}

/* Stat Cards */
.stat-card {
  padding: 1.25rem;
  text-align: center;
  height: 100%;
  border-top: 4px solid var(--color-caramel);
}

.stat-value {
