  var state = loadHomePrefs();

  function formatPKR(amount) {
    return "PKR " + Number(amount).toLocaleString("en-PK");
  }

  function safeParseJSON(raw, fallback) {
    if (!raw) {
      return fallback;
    }
    try {
      return JSON.parse(raw);
    } catch (error) {
      return fallback;
    }
  }

  function loadHomePrefs() {
    var saved = safeParseJSON(localStorage.getItem(HOME_PREFS_KEY), null);
    return {
      category: saved && typeof saved.category === "string" ? saved.category : "All",
      search: "",
      sort: saved && typeof saved.sort === "string" ? saved.sort : "featured"
    };
  }

  function saveHomePrefs() {
    try {
      localStorage.setItem(HOME_PREFS_KEY, JSON.stringify({
        category: state.category,
        sort: state.sort
      }));
    } catch (error) {
      // Ignore storage quota errors cleanly
    }
  }

  function createEl(tag, className, text) {
    var el = document.createElement(tag);
    if (className) {
      el.className = className;
    }
    if (typeof text === "string") {
      el.textContent = text;
    }
    return el;
  }

  function renderPromises() {
