      event.preventDefault();
      var value = emailInput.value.trim();
      var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

      if (!value) {
        errorEl.textContent = "Please enter your email address first.";
        errorEl.classList.remove("d-none");
        successEl.classList.add("d-none");
        emailInput.focus();
        return;
      }

      if (!emailPattern.test(value)) {
        errorEl.textContent = "Please enter a valid email address (for example, ayesha@example.com).";
        errorEl.classList.remove("d-none");
        successEl.classList.add("d-none");
        emailInput.focus();
        return;
      }

      try {
        localStorage.setItem(NEWSLETTER_KEY, value);
      } catch (error) {
        // Ignore storage error
      }
      showSavedSubscription(value);
    });

    if (unsubBtn) {
      unsubBtn.addEventListener("click", function () {
        localStorage.removeItem(NEWSLETTER_KEY);
        emailInput.value = "";
        successEl.classList.add("d-none");
        errorEl.classList.add("d-none");
      });
    }
  }

  document.addEventListener("DOMContentLoaded", function () {
    renderPromises();
    renderCategoryFilters();
    renderFeaturedBakes();
    renderWeeklySchedule();
    renderCustomerHighlights();
    initSearchAndSort();
    initNewsletter();
  });
})();

