      return;
    }
    grid.innerHTML = "";

    var query = zoneSearch.trim().toLowerCase();
    var filtered = deliveryZones.filter(function (zone) {
      var matchesGroup = zoneFilter === "All" || zone.filterGroup === zoneFilter;
      var matchesSearch = !query ||
        zone.name.toLowerCase().indexOf(query) !== -1 ||
        zone.city.toLowerCase().indexOf(query) !== -1 ||
        zone.eta.toLowerCase().indexOf(query) !== -1;
      return matchesGroup && matchesSearch;
    });

    if (filtered.length === 0) {
      emptyState.classList.remove("d-none");
      if (emptyText) {
        emptyText.textContent = query
          ? 'No delivery areas matched "' + zoneSearch.trim() + '". Message us below for custom rider quotes.'
          : "No zones match the selected filter.";
      }
      return;
    }

    emptyState.classList.add("d-none");

    filtered.forEach(function (zone) {
      var isPreferred = zone.id === preferredAreaId;
      var col = createEl("div", "col-md-6 col-lg-4");
      var card = createEl("article", "card zone-card card-hover" + (isPreferred ? " is-preferred" : ""));

      var top = createEl("div", "");
      var cityTag = createEl("p", "small fw-bold text-muted-bakery mb-1", zone.city);
      var title = createEl("h3", "h5 mb-2", zone.name);
      var eta = createEl("p", "small text-muted-bakery mb-3", zone.eta);

      top.appendChild(cityTag);
      top.appendChild(title);
      top.appendChild(eta);

      var bottom = createEl("div", "d-flex justify-content-between align-items-center pt-2 border-top");
      var fee = createEl("span", "zone-fee", zone.fee === 0 ? "Free" : formatPKR(zone.fee));
      var selectBtn = createEl(
        "button",
        "btn btn-sm " + (isPreferred ? "btn-bakery" : "btn-outline-bakery"),
        isPreferred ? "Saved Zone" : "Select Zone"
      );
      selectBtn.type = "button";
      selectBtn.addEventListener("click", function () {
        preferredAreaId = zone.id;
        try {
          localStorage.setItem(PREFERRED_AREA_KEY, preferredAreaId);
        } catch (error) {
          // Ignore storage error
        }
        var estimatorArea = document.getElementById("estimatorAreaSelect");
        if (estimatorArea) {
          estimatorArea.value = preferredAreaId;
        }
        renderEstimatorResult();
        renderDeliveryZones();
      });

      bottom.appendChild(fee);
      bottom.appendChild(selectBtn);

      card.appendChild(top);
      card.appendChild(bottom);
      col.appendChild(card);
      grid.appendChild(col);
    });
  }

  function renderGuidelines() {
    var grid = document.getElementById("guidelinesGrid");
    if (!grid) {
      return;
    }
    grid.innerHTML = "";

    deliveryGuidelines.forEach(function (item) {
      var col = createEl("div", "col-md-4");
      var card = createEl("article", "card guideline-card");
      card.appendChild(createEl("h3", "h5 mb-2", item.title));
      card.appendChild(createEl("p", "text-muted-bakery small mb-0", item.text));
      col.appendChild(card);
      grid.appendChild(col);
    });
  }

  function renderInquiryHistory() {
    var list = document.getElementById("inquiryHistoryList");
    var empty = document.getElementById("emptyInquiriesState");
    if (!list || !empty) {
      return;
    }

    list.innerHTML = "";

    if (inquiryHistory.length === 0) {
      empty.classList.remove("d-none");
      return;
    }

    empty.classList.add("d-none");

    inquiryHistory.forEach(function (entry, index) {
      var card = createEl("article", "card inquiry-item-card");
      var headerRow = createEl("div", "d-flex justify-content-between align-items-start gap-2 mb-1");
      headerRow.appendChild(createEl("strong", "small", entry.ref + " • " + entry.topic));

      var delBtn = createEl("button", "btn btn-sm btn-outline-bakery py-0 px-2", "Remove");
      delBtn.type = "button";
      delBtn.setAttribute("aria-label", "Remove inquiry " + entry.ref);
      delBtn.addEventListener("click", function () {
        inquiryHistory.splice(index, 1);
        saveInquiries();
        renderInquiryHistory();
      });

      headerRow.appendChild(delBtn);

      var meta = createEl("p", "small text-muted-bakery mb-1", entry.name + " • " + entry.submittedAt);
      var msg = createEl("p", "small mb-0", entry.message);

      card.appendChild(headerRow);
      card.appendChild(meta);
      card.appendChild(msg);
      list.appendChild(card);
    });
  }

  function initEstimatorEvents() {
    var areaSelect = document.getElementById("estimatorAreaSelect");
    var slotSelect = document.getElementById("estimatorSlotSelect");
    var searchInput = document.getElementById("zoneSearchInput");
    var resetBtn = document.getElementById("resetZoneFilterBtn");

    if (areaSelect) {
      areaSelect.addEventListener("change", function () {
        preferredAreaId = areaSelect.value;
        try {
          localStorage.setItem(PREFERRED_AREA_KEY, preferredAreaId);
        } catch (error) {
          // Ignore storage error
        }
        renderEstimatorResult();
        renderDeliveryZones();
      });
    }

    if (slotSelect) {
      slotSelect.addEventListener("change", function () {
        preferredSlotId = slotSelect.value;
        try {
          localStorage.setItem(PREFERRED_SLOT_KEY, preferredSlotId);
        } catch (error) {
          // Ignore storage error
        }
        renderEstimatorResult();
      });
    }

    if (searchInput) {
      searchInput.addEventListener("input", function () {
        zoneSearch = searchInput.value;
        renderDeliveryZones();
      });
    }

    if (resetBtn) {
      resetBtn.addEventListener("click", function () {
        zoneFilter = "All";
        zoneSearch = "";
        if (searchInput) {
          searchInput.value = "";
        }
        renderZoneFilterBar();
        renderDeliveryZones();
      });
    }
  }

  function setFieldError(inputEl, errorEl, message) {
    if (!inputEl || !errorEl) {
      return;
    }
    if (message) {
      errorEl.textContent = message;
      errorEl.classList.remove("d-none");
      inputEl.classList.add("is-invalid-field");
      inputEl.setAttribute("aria-invalid", "true");
    } else {
      errorEl.textContent = "";
      errorEl.classList.add("d-none");
      inputEl.classList.remove("is-invalid-field");
      inputEl.removeAttribute("aria-invalid");
    }
  }

  function initContactForm() {
    var form = document.getElementById("contactForm");
    var nameInput = document.getElementById("contactName");
    var phoneInput = document.getElementById("contactPhone");
    var emailInput = document.getElementById("contactEmail");
    var topicSelect = document.getElementById("contactTopic");
    var areaSelect = document.getElementById("contactArea");
    var messageInput = document.getElementById("contactMessage");
    var feedback = document.getElementById("inquiryFeedback");
    var resetBtn = document.getElementById("resetContactFormBtn");
    var clearInquiriesBtn = document.getElementById("clearInquiriesBtn");

    var nameErr = document.getElementById("contactNameError");
    var phoneErr = document.getElementById("contactPhoneError");
    var emailErr = document.getElementById("contactEmailError");
    var topicErr = document.getElementById("contactTopicError");
    var messageErr = document.getElementById("contactMessageError");

    if (!form) {
      return;
    }

    // Restore saved draft from localStorage
    var draft = safeParseJSON(localStorage.getItem(CONTACT_DRAFT_KEY), null);
    if (draft) {
      if (draft.name) { nameInput.value = draft.name; }
      if (draft.phone) { phoneInput.value = draft.phone; }
      if (draft.email) { emailInput.value = draft.email; }
      if (draft.topic) { topicSelect.value = draft.topic; }
      if (draft.area) { areaSelect.value = draft.area; }
      if (draft.message) { messageInput.value = draft.message; }
    }

    function saveDraft() {
      try {
        localStorage.setItem(CONTACT_DRAFT_KEY, JSON.stringify({
          name: nameInput.value,
          phone: phoneInput.value,
          email: emailInput.value,
          topic: topicSelect.value,
          area: areaSelect.value,
          message: messageInput.value
        }));
      } catch (error) {
        // Ignore storage error
      }
    }

    [nameInput, phoneInput, emailInput, topicSelect, areaSelect, messageInput].forEach(function (field) {
      if (field) {
        field.addEventListener("input", saveDraft);
        field.addEventListener("change", saveDraft);
      }
    });

    form.addEventListener("submit", function (event) {
      event.preventDefault();

      var nameVal = nameInput.value.trim();
      var phoneDigits = phoneInput.value.replace(/[\s\-()]/g, "");
      var emailVal = emailInput.value.trim();
      var topicVal = topicSelect.value.trim();
      var areaVal = areaSelect.value.trim() || "Unspecified area";
      var messageVal = messageInput.value.trim();

      var isValid = true;
      var firstInvalid = null;

      if (nameVal.length < 2) {
        setFieldError(nameInput, nameErr, "Please enter your full name (at least 2 characters).");
        isValid = false;
        firstInvalid = firstInvalid || nameInput;
      } else {
        setFieldError(nameInput, nameErr, "");
      }

      var phonePattern = /^(\+92|0)?3\d{9}$/;
      if (!phonePattern.test(phoneDigits)) {
        setFieldError(phoneInput, phoneErr, "Enter a valid Pakistani mobile number (e.g., 0300-1234567 or +923001234567).");
        isValid = false;
        firstInvalid = firstInvalid || phoneInput;
      } else {
        setFieldError(phoneInput, phoneErr, "");
      }

      var emailPattern = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;
      if (!emailPattern.test(emailVal)) {
        setFieldError(emailInput, emailErr, "Please enter a valid email address.");
        isValid = false;
        firstInvalid = firstInvalid || emailInput;
      } else {
        setFieldError(emailInput, emailErr, "");
      }

      if (!topicVal) {
        setFieldError(topicSelect, topicErr, "Please select an inquiry topic.");
        isValid = false;
        firstInvalid = firstInvalid || topicSelect;
      } else {
        setFieldError(topicSelect, topicErr, "");
      }

      if (messageVal.length < 12) {
        setFieldError(messageInput, messageErr, "Please share at least 12 characters so our baker can help you.");
        isValid = false;
        firstInvalid = firstInvalid || messageInput;
      } else {
        setFieldError(messageInput, messageErr, "");
      }

      if (!isValid) {
        if (feedback) {
          feedback.classList.add("d-none");
        }
        if (firstInvalid) {
          firstInvalid.focus();
        }
        return;
      }

      var refCode = "TSO-INQ-" + Math.floor(1000 + Math.random() * 9000);
      var newInquiry = {
        ref: refCode,
        name: nameVal,
        phone: phoneInput.value.trim(),
        email: emailVal,
        topic: topicVal,
        area: areaVal,
        message: messageVal,
        submittedAt: new Date().toLocaleString("en-PK", { dateStyle: "medium", timeStyle: "short" })
      };

      inquiryHistory.unshift(newInquiry);
      saveInquiries();
      renderInquiryHistory();

      localStorage.removeItem(CONTACT_DRAFT_KEY);
      form.reset();

      if (feedback) {
        feedback.textContent = "Thank you, " + nameVal + "! Inquiry " + refCode + " has been saved. Our F-8/3 kitchen desk responds within 2 hours during bakery hours.";
        feedback.classList.remove("d-none");
      }
    });

    if (resetBtn) {
      resetBtn.addEventListener("click", function () {
        form.reset();
        localStorage.removeItem(CONTACT_DRAFT_KEY);
        setFieldError(nameInput, nameErr, "");
        setFieldError(phoneInput, phoneErr, "");
        setFieldError(emailInput, emailErr, "");
        setFieldError(topicSelect, topicErr, "");
        setFieldError(messageInput, messageErr, "");
        if (feedback) {
          feedback.classList.add("d-none");
        }
      });
    }

    if (clearInquiriesBtn) {
      clearInquiriesBtn.addEventListener("click", function () {
        inquiryHistory = [];
        saveInquiries();
        renderInquiryHistory();
      });
    }
  }

  document.addEventListener("DOMContentLoaded", function () {
    renderContactChannels();
    populateSelects();
    renderEstimatorResult();
    renderZoneFilterBar();
    renderDeliveryZones();
    renderGuidelines();
    renderInquiryHistory();
    initEstimatorEvents();
    initContactForm();
  });
})();

args.CommandLine:
powershell -NoProfile -Command "
$files = @(
  'index.html','pages/about.html','pages/contact.html',
  'css/home.css','css/about.css','css/contact.css',
  'js/site-nav.js','js/home.js','js/about.js','js/contact.js',
  'images/hero-oven-spread.svg','images/baker-kitchen.svg'
);
Write-Host '=== File Existence & Sizes ===';
foreach ($f in $files) {
  if (Test-Path $f) {
    $len = (Get-Item $f).Length;
    Write-Host ('OK  ' + $f + ' (' + $len + ' bytes)');
  } else {
    Write-Host ('MISS ' + $f);
    exit 1;
  }
}
Write-Host '=== Check forbidden patterns ===';
$targets = @('index.html','pages/about.html','pages/contact.html','js/site-nav.js','js/home.js','js/about.js','js/contact.js');
foreach ($t in $targets) {
  $c = Get-Content $t -Raw;
  if ($c -match 'bootstrap\.bundle|bootstrap\.min\.js|jquery|lorem\s+ipsum') {
    Write-Host ('FORBIDDEN MATCH in ' + $t);
    exit 1;
  }
}
Write-Host 'OK  No Bootstrap JS, jQuery, or lorem ipsum found.';
Write-Host '=== Check JS syntax with node if available ===';
if (Get-Command node -ErrorAction SilentlyContinue) {
  foreach ($j in @('js/site-nav.js','js/home.js','js/about.js','js/contact.js')) {
    node --check $j;
    if ($LASTEXITCODE -ne 0) { exit 1; }
  }
  Write-Host 'OK  All 4 JS files passed node --check.';
} else {
  Write-Host 'Node not installed; skipped node --check.';
}
Write-Host '=== Check local asset references in HTML ===';
foreach ($h in @('index.html','pages/about.html','pages/contact.html')) {
  $dir = Split-Path $h -Parent;
  $content = Get-Content $h -Raw;
  $matches = [regex]::Matches($content, '(?:src|href)=""([^""]+)""');
  foreach ($m in $matches) {
    $val = $m.Groups[1].Value;
    if ($val -match '^(https?:|mailto:|tel:|#)') { continue; }
    $resolved = if ($dir) { Join-Path $dir $val } else { $val };
    $exists = Test-Path $resolved;
    Write-Host (($exists ? 'OK  ' : 'PLAN ') + $h + ' -> ' + $val);
  }
}
"

args.Content:
/**
 * Shared vanilla JavaScript for navigation toggle (no Bootstrap JS),
 * safe localStorage helpers, light/cozy theme toggle, and live basket badge sync.
 */
(function () {
  "use strict";

  var CART_STORAGE_KEY = "sweetOvenCart";
  var THEME_STORAGE_KEY = "sweetOvenTheme";
  var memoryTheme = "light";

  function safeGetStorage(key) {
    try {
      return window.localStorage ? window.localStorage.getItem(key) : null;
    } catch (error) {
      return null;
    }
  }

  function safeSetStorage(key, value) {
    try {
      if (window.localStorage) {
        window.localStorage.setItem(key, value);
        return true;
      }
      return false;
    } catch (error) {
      return false;
    }
  }

  function safeRemoveStorage(key) {
    try {
      if (window.localStorage) {
        window.localStorage.removeItem(key);
        return true;
      }
      return false;
    } catch (error) {
      return false;
    }
  }

  function getTheme() {
    var saved = safeGetStorage(THEME_STORAGE_KEY);
    if (saved === "cozy" || saved === "light") {
      memoryTheme = saved;
      return saved;
    }
    return document.documentElement.getAttribute("data-theme") === "cozy" ? "cozy" : memoryTheme;
  }

  function applyTheme(theme) {
    var normalized = theme === "cozy" ? "cozy" : "light";
    memoryTheme = normalized;

    if (normalized === "cozy") {
      document.documentElement.setAttribute("data-theme", "cozy");
    } else {
      document.documentElement.removeAttribute("data-theme");
    }

    safeSetStorage(THEME_STORAGE_KEY, normalized);

    var toggleBtn = document.getElementById("themeToggleBtn");
    if (toggleBtn) {
      var isCozy = normalized === "cozy";
      toggleBtn.setAttribute("aria-pressed", String(isCozy));
      toggleBtn.setAttribute(
        "aria-label",
        isCozy ? "Switch to light cream theme" : "Switch to cozy dark theme"
      );
      toggleBtn.textContent = isCozy ? "Light Theme" : "Cozy Theme";
    }
  }

  function initThemeToggle() {
    var toggleBtn = document.getElementById("themeToggleBtn");
    applyTheme(getTheme());

    if (!toggleBtn) {
      return;
    }

    toggleBtn.addEventListener("click", function () {
      var nextTheme = getTheme() === "cozy" ? "light" : "cozy";
      applyTheme(nextTheme);
    });
  }

  function initNavbarToggle() {
    var toggleBtn = document.querySelector(".navbar-toggler");
    var navCollapse = document.getElementById("mainNavbar");

    if (!toggleBtn || !navCollapse) {
      return;
    }

    toggleBtn.addEventListener("click", function () {
      var isExpanded = navCollapse.classList.toggle("show");
      toggleBtn.setAttribute("aria-expanded", String(isExpanded));
    });

    // Close mobile menu when a nav link is selected
    var navLinks = navCollapse.querySelectorAll(".nav-link");
    navLinks.forEach(function (link) {
      link.addEventListener("click", function () {
        if (navCollapse.classList.contains("show")) {
          navCollapse.classList.remove("show");
          toggleBtn.setAttribute("aria-expanded", "false");
        }
      });
    });

    // Allow Escape key to close an open mobile menu
    document.addEventListener("keydown", function (event) {
      if (event.key === "Escape" && navCollapse.classList.contains("show")) {
        navCollapse.classList.remove("show");
        toggleBtn.setAttribute("aria-expanded", "false");
        toggleBtn.focus();
      }
    });
  }

  function getSavedCartCount() {
    var raw = safeGetStorage(CART_STORAGE_KEY);
    if (!raw) {
      return 0;
    }
    try {
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) {
        return 0;
      }
      return parsed.reduce(function (total, item) {
        var qty = Number(item && item.quantity);
        return total + (Number.isFinite(qty) && qty > 0 ? qty : 0);
      }, 0);
    } catch (error) {
      return 0;
    }
  }

  function updateNavCartBadge() {
    var badge = document.getElementById("navCartCount");
    if (!badge) {
      return;
    }
    var count = getSavedCartCount();
    badge.textContent = String(count);
    badge.setAttribute("aria-label", count + " items in cart");
  }

  document.addEventListener("DOMContentLoaded", function () {
    initThemeToggle();
    initNavbarToggle();
    updateNavCartBadge();
  });

  // Expose helpers so page scripts can share safe storage & badge updates
  window.SweetOvenNav = {
    updateCartBadge: updateNavCartBadge,
    safeGetStorage: safeGetStorage,
    safeSetStorage: safeSetStorage,
    safeRemoveStorage: safeRemoveStorage,
    getTheme: getTheme,
    setTheme: applyTheme
  };
})();

/* ==========================================================================
   The Sweet Oven - Home Page Stylesheet (index.html)
   Loaded AFTER Bootstrap 5.3.3 CSS & css/styles.css
   ========================================================================== */

.nav-cart-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 1.35rem;
  height: 1.35rem;
  padding: 0 0.35rem;
  margin-left: 0.3rem;
  border-radius: 999px;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1;
}

.theme-toggle-btn {
  background-color: var(--color-pink-soft);
  border: 1.5px solid var(--color-brown);
  color: var(--color-brown);
  font-weight: 700;
  border-radius: 999px;
  padding: 0.38rem 0.85rem;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.theme-toggle-btn:hover {
  background-color: var(--color-pink);
  color: var(--color-brown);
}

/* Visible :focus-visible outlines (3px caramel #B5601E with offset) */
a:focus-visible,
button:focus-visible,
.btn:focus-visible,
.navbar-toggler:focus-visible,
.theme-toggle-btn:focus-visible,
input:focus-visible,
select:focus-visible,
textarea:focus-visible,
.form-control:focus-visible,
.form-select:focus-visible,
.carousel-btn:focus-visible,
.carousel-dot:focus-visible,
.filter-pill:focus-visible {
  outline: 3px solid #B5601E;
  outline-offset: 3px;
  box-shadow: 0 0 0 5px rgba(243, 182, 192, 0.45);
}

/* Remembered Visit Banner */
.visit-greeting-bar {
  background-color: var(--color-surface);
  border: 1.5px solid var(--color-pink);
  border-left: 5px solid var(--color-caramel);
  border-radius: var(--radius-sm);
  padding: 0.6rem 1rem;
  color: var(--color-brown);
  font-weight: 700;
  font-size: 0.95rem;
  display: inline-block;
}

/* Hero Section */
.hero-section {
  background: linear-gradient(135deg, var(--color-cream) 0%, var(--color-pink-soft) 100%);
  border-bottom: 1px solid var(--color-border);
}

.eyebrow-pill {
  display: inline-block;
  background-color: var(--color-pink);
  color: var(--color-brown);
  font-weight: 700;
  font-size: 0.85rem;
  letter-spacing: 0.03em;
  padding: 0.35rem 0.9rem;
  border-radius: 999px;
}

.hero-title {
  font-size: clamp(2rem, 3.8vw, 3.1rem);
  color: var(--color-brown);
}

.hero-lead {
  font-size: 1.08rem;
  color: var(--color-muted);
  max-width: 38rem;
}

.hero-illustration {
  width: 100%;
  max-width: 480px;
  height: auto;
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
}

.hero-meta-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem 1.5rem;
  font-size: 0.94rem;
  color: var(--color-brown);
}

.hero-meta-item {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
}

.meta-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background-color: var(--color-caramel);
  flex-shrink: 0;
}

/* Promise Pillars */
.promise-card {
  height: 100%;
  padding: 1.35rem;
  border-left: 4px solid var(--color-caramel);
}

.promise-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 2.3rem;
  height: 2.3rem;
  border-radius: var(--radius-sm);
  background-color: var(--color-pink-soft);
  color: var(--color-brown);
  font-weight: 700;
  font-family: var(--font-heading);
  margin-bottom: 0.75rem;
}

/* Best Sellers Carousel */
.best-sellers-carousel {
  background-color: var(--color-cream);
  border: 2px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow-soft);
}

.carousel-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.carousel-status-hint {
  font-size: 0.85rem;
  color: var(--color-muted);
  font-weight: 600;
}

.carousel-controls {
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.carousel-btn {
  background-color: var(--color-surface);
  color: var(--color-brown);
  border: 1.5px solid var(--color-brown);
  border-radius: var(--radius-sm);
  padding: 0.42rem 0.9rem;
  font-weight: 700;
  font-size: 0.9rem;
  cursor: pointer;
  transition: background-color 0.2s ease, color 0.2s ease;
}

.carousel-btn:hover:not(:disabled) {
  background-color: var(--color-pink);
  color: var(--color-brown);
}

.carousel-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.carousel-viewport {
  overflow: hidden;
  border-radius: var(--radius-md);
}

.carousel-track {
  display: flex;
  transition: transform 0.35s ease;
}

.carousel-slide {
  flex: 0 0 100%;
  min-width: 100%;
}

.carousel-slide-card {
