  color: var(--color-brown);
  font-weight: 700;
  font-size: 0.88rem;
  padding: 0.4rem 0.9rem;
  border-radius: 999px;
  cursor: pointer;
  transition: background-color 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.zone-filter-btn:hover {
  background-color: var(--color-pink-soft);
  border-color: var(--color-caramel);
}

.zone-filter-btn.is-active {
  background-color: var(--color-brown);
  border-color: var(--color-brown);
  color: var(--color-cream);
}

.zone-card {
  height: 100%;
  padding: 1.2rem;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}

.zone-card.is-preferred {
  border: 2px solid var(--color-caramel);
  background-color: var(--color-pink-soft);
}

.zone-fee {
  font-family: var(--font-heading);
  font-size: 1.2rem;
  font-weight: 700;
  color: var(--color-caramel-dark);
}

/* Estimator / Delivery Checker Card */
.estimator-card {
  background-color: var(--color-surface);
  border: 2px solid var(--color-pink);
  border-radius: var(--radius-lg);
  box-shadow: var(--shadow-soft);
}

.estimator-result {
  background-color: var(--color-cream);
  border: 1.5px solid var(--color-border);
  border-radius: var(--radius-md);
  padding: 1.1rem;
}

.estimator-result.is-unserved {
  border-color: #9E2A2B;
  background-color: #FFF1F0;
}

.estimator-result.is-served {
  border-color: var(--color-caramel);
}

/* Form Validation & Feedback */
.field-error-msg {
  color: #9E2A2B;
  font-size: 0.85rem;
  font-weight: 700;
  margin-top: 0.3rem;
}

.is-invalid-field {
  border-color: #9E2A2B !important;
}

.feedback-banner {
  background-color: var(--color-brown);
  color: var(--color-cream);
  border-left: 5px solid var(--color-pink);
  border-radius: var(--radius-sm);
  padding: 0.85rem 1.1rem;
  font-weight: 600;
}

.inquiry-item-card {
  padding: 1rem 1.15rem;
  border-left: 4px solid var(--color-caramel);
}

.empty-state-box {
  background-color: var(--color-surface);
  border: 1.5px dashed var(--color-input-border);
  border-radius: var(--radius-md);
  padding: 1.75rem 1.25rem;
  text-align: center;
}

.guideline-card {
  height: 100%;
  padding: 1.2rem;
}

